<section data-speech-category="inventory" x-show="tab==='inventory'" x-cloak @vsg-audio.window="sounds=$event.detail" x-data="inventoryLibrary(@js(route('inventory.show',$story)))" @vsg-inventory-refresh.window="load()">
<header class="mb-5 flex items-center justify-between gap-4"><div><h2 class="font-serif text-2xl">Inventory</h2><p class="mt-1 text-sm text-stone-500">Shared items for every page and scene. Changes save automatically.</p></div><button type="button" class="btn-primary" @click="create()" :disabled="loading || items.length>=100">+ New item</button></header>
<p x-show="loading">Loading inventory…</p><p x-show="!loading && !items.length" class="rounded-xl border border-dashed p-8 text-center">Create an item, choose its image, then link it to a clickable area in Scenes.</p>
<div class="grid gap-5 xl:grid-cols-2"><template x-for="item in items" :key="item.id"><article class="space-y-4 rounded-xl border border-stone-200 bg-white p-4 dark:border-stone-700 dark:bg-stone-900">
<div class="flex items-start gap-4"><button type="button" class="grid h-28 w-28 shrink-0 place-items-center overflow-hidden rounded-lg border text-xs" @click="chooseImage(item)" :aria-label="'Choose image for '+item.name"><template x-if="asset(item.asset_id)"><img :src="asset(item.asset_id).url" :alt="item.name" class="h-full w-full object-contain"></template><span x-show="!asset(item.asset_id)">Choose image</span></button><div class="min-w-0 flex-1 space-y-3"><label class="field">Item name<input x-model="item.name" maxlength="160" required @input="changed()"></label><button type="button" class="text-xs underline" @click="chooseImage(item)">Change image</button></div><button type="button" class="text-xs underline" @click="requestDelete(item)">Delete</button></div>
<div class="grid grid-cols-2 gap-3"><template x-for="field in ['sound_id','action_sound_id']" :key="field"><label class="field"><span x-text="field==='sound_id'?'Click sound':'Inventory sound'"></span><div class="audio-select-row" x-data="audioPreview('inventory')" x-effect="setSound(sounds.find(s=>s.id===Number(item[field])))" @vsg-audio-categories.window="categories=$event.detail" @vsg-audio-preview-stop.window="stop()"><select class="audio-category-select" aria-label="Audio category" x-model="category"><option value="">All categories</option><template x-for="(name,key) in categories" :key="key"><option :value="key" x-text="name"></option></template></select><div class="min-w-0 flex-1"><select :value="item[field] ?? ''" @change="item[field]=$event.target.value||null;changed()"><option value="">Default from story bible</option><option value="silent">No sound (silent)</option><template x-for="s in sounds.filter(s=>!category||(s.category||'effects')===category||Number(s.id)===Number(sound?.id))" :key="s.id"><option :value="s.id" x-text="s.name"></option></template></select></div><button type="button" class="btn-secondary audio-preview-button" :disabled="!sound?.url" :aria-label="playing?'Stop audio preview':'Play selected audio'" @click="toggle()"><span x-text="playing?'\u25A0':'\u25B6'"></span></button></div></label></template></div><label class="field">Description<textarea x-model="item.description" rows="3" maxlength="3000" @input="changed()" placeholder="What the player sees when inspecting this item."></textarea></label>
<label class="field">Description position<select x-model="item.description_position" @change="changed()"><option value="top">Top</option><option value="bottom">Bottom</option></select></label>
<div class="space-y-2"><div class="flex items-center justify-between"><h3 class="text-sm font-semibold">Actions</h3><button type="button" class="text-xs underline" @click="addAction(item)" :disabled="(item.actions||[]).length>=50">+ Action</button></div><template x-for="action in item.actions||[]" :key="action.id"><div class="flex items-end gap-2"><label class="field min-w-0 flex-1">Action<input x-model="action.label" maxlength="160" @input="changed()"></label><label class="field min-w-0 flex-1">Replace with<select x-model="action.target_id" @change="changed()"><option :value="null">Choose item</option><template x-for="target in items" :key="target.id"><option :value="target.id" x-text="target.name"></option></template></select></label><button type="button" class="text-xs underline" @click="item.actions=item.actions.filter(a=>a.id!==action.id);changed()">Remove</button></div></template></div>
<div class="border-t pt-3 dark:border-stone-700"><h3 class="mb-2 text-xs font-semibold">Used in pages &amp; scenes</h3><ul class="space-y-1"><template x-for="use in uses[item.id]||[]" :key="use.page_id+':'+use.scene_id"><li><a :href="use.url" class="text-xs underline" x-text="use.label"></a></li></template></ul><p x-show="!(uses[item.id]||[]).length" class="text-xs text-stone-500">Not linked to a scene yet.</p></div>
</article></template></div>
<dialog x-ref="inventoryImages" class="inventory-image-dialog reference-dialog rounded-xl bg-white text-stone-900 dark:bg-stone-900 dark:text-stone-100" @click="if($event.target===$el)$el.close()"><header class="flex items-center justify-between border-b p-4"><h2 class="font-serif text-xl">Choose item image</h2><button type="button" class="btn-secondary" @click="$refs.inventoryImages.close()">Close</button></header><div class="min-h-0 overflow-y-auto p-4"><div class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="a in assets" :key="a.id"><button type="button" class="overflow-hidden rounded-lg border p-2 text-left" @click="selectImage(a.id)"><img :src="a.url" :alt="a.name" class="aspect-square w-full object-contain" loading="lazy"><span class="text-xs" x-text="a.name"></span></button></template></div><p x-show="!assets.length">Generate or upload an image first.</p></div><footer class="border-t p-4"><button type="button" class="text-xs underline" @click="selectImage(null)">Remove image</button></footer></dialog>
<dialog x-ref="inventoryDelete" class="rounded-xl bg-white p-6 text-stone-900 dark:bg-stone-900 dark:text-stone-100"><h2 class="font-serif text-xl">Delete inventory item?</h2><p class="my-4 text-sm">Items linked to scenes or replacement actions must be unlinked first.</p><div class="flex justify-end gap-3"><button type="button" class="btn-secondary" @click="$refs.inventoryDelete.close()">Cancel</button><button type="button" class="btn-primary" @click="remove()">Delete item</button></div></dialog>
</section>
